example.code:
ILetterControllerSettings settings = new LetterControllerSettings();
settings.SetBehavior("RaidEnemy", LetterBehavior.Ignore);
Assert.AreEqual(LetterBehavior.Ignore, settings.GetBehavior("RaidEnemy"));

var incident = new IncidentDef { defName = "RaidEnemy" };
using (IncidentContext.EnterScope(incident))
{
    Assert.AreEqual("RaidEnemy", IncidentContext.CurrentIncident?.defName);
}
Assert.IsNull(IncidentContext.CurrentIncident);

var settings = new LetterControllerSettings();
settings.SetBehavior("RaidEnemy", LetterBehavior.Pause);
Assert.AreEqual(LetterBehavior.Pause, settings.GetBehavior("RaidEnemy"));

// Context is automatically populated during IncidentWorker execution:
IncidentWorkerPatch.Prefix(worker, out var state);
try { /* incident runs */ }
finally { IncidentWorkerPatch.Finalizer(null, state); }

var service = new IncidentFilterService();
service.SetItems(new[] { new IncidentItem("RaidEnemy", "Enemy Raid", "Core") });
service.SearchQuery = "Enemy";
service.Update(new LetterControllerSettings());
Assert.AreEqual(1, service.FilteredItems.Count);

var incident = new IncidentDef { defName = "RaidEnemy" };
var settings = new LetterControllerSettings();
settings.SetBehavior("RaidEnemy", LetterBehavior.Ignore);
bool suppress = LetterInterceptionPolicy.ShouldSuppress(incident, settings);
Assert.IsTrue(suppress);
